export class PointV1 {
    /**
     * The alignment that a parent pads a `PointV1` to: the largest
     * alignment of its arrays and nested tables, or 1
     */
    static readonly ALIGNMENT = 1;

    /**
     * The byte length of a `PointV1`: its offsets and its fields, whose sizes
     * the schema fixes, so that its parent writes it whole
     */
    static readonly SIZE = 24;

    declare private readonly _reader: TableReader;
    declare private readonly _position: number;

    /** Reads the table at `position`, as its parent's getter finds it */
    constructor(reader: TableReader, position: number) {
        this._reader = reader;
        this._position = position;
    }

    /**
     * Reads every field of the table at `position`, as `fields()` does,
     * without creating a `PointV1`
     */
    static read(reader: TableReader, position: number): PointV1Fields {
        return {
            x: reader.getFloat64(reader.fieldOffset(position, 0)),
            y: reader.getFloat64(reader.fieldOffset(position, 1))
        };
    }

    /**
     * Adds a `PointV1` to its parent's sizer, after the field or
     * vector that holds it
     */
    static size(sizer: TableSizer, _fields: PointV1Fields): void {
        sizer.addTableBytes(1, PointV1.SIZE);
    }

    /**
     * Writes a `PointV1` where its parent's writer is, after the
     * field that holds it
     */
    static write(writer: TableWriter, fields: PointV1Fields): void {
        PointV1.writeAt(
            writer.target(),
            writer.reserveTableBytes(PointV1.SIZE),
            fields
        );
    }

    /**
     * Writes a `PointV1` at `offset` in `bytes`, as its parent holds it: its
     * offsets, and then its fields at them
     *
     * @throws {RangeError} If `bytes` end before the `PointV1` does.
     */
    static writeAt(
        bytes: Uint8Array,
        offset: number,
        fields: PointV1Fields
    ): void {
        bytes[offset] = 8;
        bytes[offset + 1] = 0;
        bytes[offset + 2] = 0;
        bytes[offset + 3] = 0;
        bytes[offset + 4] = 16;
        bytes[offset + 5] = 0;
        bytes[offset + 6] = 0;
        bytes[offset + 7] = 0;

        writeFloat64(bytes, offset + 8, fields.x);
        writeFloat64(bytes, offset + 16, fields.y);
    }

    x(): number {
        return this._reader.getFloat64(
            this._reader.fieldOffset(this._position, 0)
        );
    }

    y(): number {
        return this._reader.getFloat64(
            this._reader.fieldOffset(this._position, 1)
        );
    }

    /**
     * Reads every field into the `PointV1Fields` that writes it, nested
     * tables and the items of vectors and arrays of structs included
     */
    fields(): PointV1Fields {
        return PointV1.read(this._reader, this._position);
    }
}

/** The fields of a `PointV1`, to write */
export interface PointV1Fields {
    x: number;
    y: number;
}

